# seção 14: menu lateral, lixeira, modelos, importar e colar entre mapas
import json
from playwright.sync_api import sync_playwright
exec(open('base_lista_editor.py').read().split('with sync_playwright')[0])
falhas=[]
def ok(nome,cond,extra=''):
    print(('OK  ' if cond else 'FALHOU ')+nome,extra)
    if not cond: falhas.append(nome)
A='11111111-1111-4111-8111-111111111111'; B='22222222-2222-4222-8222-222222222222'
def mapa(id,titulo,filhos,extra=None):
    return {'id':id,'titulo':titulo,'favorito':False,'atualizado_em':'2026-10-30T10:00:00Z','criado_em':'2026-10-30T10:00:00Z','excluido_em':None,'dados':{'nodeData':{'id':'r','topic':titulo,'children':filhos},'arrows':[],'summaries':[]}}
MA=mapa(A,'Mapa A',[{'id':'a','topic':'Ramo A','direction':1,'children':[{'id':'a1','topic':'Filho A1','metadata':{'img':'u1/%s/foto.webp'%A},'image':{'url':'data:image/gif;base64,R0lGODlhAQABAAAAACw=','width':50,'height':50},'children':[{'id':'a11','topic':'Neto A11'}]}]}])
MB=mapa(B,'Mapa B',[{'id':'b','topic':'Ramo B','direction':1}])
def no(pg,i): return pg.evaluate("i=>{const f=n=>n.id===i?n:(n.children||[]).map(f).find(Boolean);return JSON.parse(JSON.stringify(f(mind.getData().nodeData),(k,v)=>k==='parent'?undefined:v))}",i)
def clica(pg,i):
    r=pg.evaluate("i=>{const r=mind.findEle(i).getBoundingClientRect();return [r.x+r.width/2,r.y+r.height/2]}",i); pg.mouse.click(*r); pg.wait_for_timeout(150)
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':1280,'height':800},permissions=['clipboard-read','clipboard-write'])
    pg=ctx.new_page(); pg.route('**/*',rotas); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://local/mind/')
    pg.evaluate("([a,b])=>{sessionStorage.setItem('mocklog','1');sessionStorage.setItem('mockdb',JSON.stringify([a,b]));sessionStorage.setItem('mockfiles',JSON.stringify({'u1/%s/foto.webp':'data:image/gif;base64,R0lGODlhAQABAAAAACw='}))}"%A,[MA,MB])
    pg.goto('http://local/mind/?t=1#/'); pg.wait_for_selector('#lista',state='visible'); pg.wait_for_timeout(500)

    # ---- menu lateral ----
    ok('LAT nome e logo',pg.text_content('.lat-marca b')=='PrivoMind' and pg.evaluate("document.querySelector('.lat-marca img').getAttribute('src')")=='/logo-rosa.svg')
    ok('LAT 4 itens: Lar, Todos os mapas, Favoritos, Lixeira',pg.evaluate("[...document.querySelectorAll('#lat-nav a')].map(a=>a.textContent.trim())")==['Lar','Todos os mapas','Favoritos','Lixeira'])
    ok('LAT botões do topo',all(pg.is_visible(i) for i in ['#novo','#btn-modelos','#btn-importar']) and 'Navegue pelos modelos' in pg.text_content('#btn-modelos'))
    ok('LAT Lar mostra mapas recentes',pg.locator('#mapas li[data-id]').count()==2 and pg.is_visible('#sec-lar'))
    pg.screenshot(path=OUT+'/lar.png')
    pg.click('#lat-nav [data-sec=fav]'); pg.mouse.move(1000,650); pg.wait_for_timeout(450)
    ok('LAT Favoritos vazio',pg.locator('#mapas li[data-id]').count()==0 and 'Nenhum favorito' in pg.text_content('#mapas') and not pg.is_visible('#sec-lar'))
    pg.click('#lat-nav [data-sec=todos]'); pg.mouse.move(1000,650); pg.wait_for_timeout(450)
    pg.locator('#mapas li[data-id="%s"] [data-a=fav]'%A).click(); pg.wait_for_timeout(200)
    pg.click('#lat-nav [data-sec=fav]'); pg.mouse.move(1000,650); pg.wait_for_timeout(450)
